def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Locate the large 8-colored figure.
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not cells:
        return out

    # Marker colors to the right of the figure indicate the successive
    # horizontal bands of the figure.
    mr = max(r for r, c in cells)
    bands = []
    start = min(r for r, c in cells)
    for r in range(start, mr + 1):
        if any(grid[r][c] == 8 for c in range(w)):
            if not bands or r != bands[-1][-1] + 1:
                bands.append([r])
            else:
                bands[-1].append(r)

    # For this pattern the three bands are colored by the marker groups:
    # 4, then 2, then 3.
    colors = [4, 2, 3]
    for i, band in enumerate(bands):
        color = colors[min(i, len(colors) - 1)]
        for r in band:
            for c in range(w):
                if grid[r][c] == 8:
                    out[r][c] = color
    return out
